/**
 * Creates an offscreen Canvas landmass sampler.
 * @param {number} width
 * @param {number} height
 * @returns {{ isLand: (lat: number, lon: number) => boolean, canvas: HTMLCanvasElement, renderPromise: Promise<void> }}
 */
export function createLandmassSampler(width = 1024, height = 512) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  
  // Fill black (ocean)
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, width, height);

  let imageData = null;

  const renderPromise = new Promise((resolve) => {
    const img = new Image();
    const blob = new Blob([WORLD_LAND_SVG], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);

    img.onload = () => {
      ctx.drawImage(img, 0, 0, width, height);
      imageData = ctx.getImageData(0, 0, width, height).data;
      URL.revokeObjectURL(url);
      resolve();
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      resolve();
    };
    img.src = url;
  });

  return {
    renderPromise,
    isLand: (lat, lon) => {
      if (!imageData) return false;
      const u = (lon + 180) / 360;
      const v = (90 - lat) / 180;
      const px = Math.min(width - 1, Math.max(0, Math.floor(u * width)));
      const py = Math.min(height - 1, Math.max(0, Math.floor(v * height)));
      const idx = (py * width + px) * 4;
      return imageData[idx] > 60;
    },
    getCanvas: () => canvas
  };
}


