/**
 * Creates a luminescent 2048x1024 Earth canvas texture with glowing continents and oceans.
 * @returns { canvas: HTMLCanvasElement, renderPromise: Promise<HTMLCanvasElement> }
 */
export function createLuminescentEarthTexture(width = 2048, height = 1024) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // 1. Deep Space-Ocean Gradient
  const oceanGrad = ctx.createRadialGradient(width / 2, height / 2, 100, width / 2, height / 2, width);
  oceanGrad.addColorStop(0, '#091b36');
  oceanGrad.addColorStop(0.5, '#051024');
  oceanGrad.addColorStop(1, '#020612');
  ctx.fillStyle = oceanGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Cyber Longitude & Latitude Graticule Lines
  ctx.strokeStyle = 'rgba(0, 240, 255, 0.07)';
  ctx.lineWidth = 1.0;
  for (let lon = -180; lon <= 180; lon += 15) {
    const x = ((lon + 180) / 360) * width;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
  }
  for (let lat = -90; lat <= 90; lat += 15) {
    const y = ((90 - lat) / 180) * height;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(width, y);
    ctx.stroke();
  }

  // 3. Equator & Prime Meridian Glow Highlights
  ctx.strokeStyle = 'rgba(0, 240, 255, 0.25)';
  ctx.lineWidth = 2.0;
  ctx.beginPath();
  ctx.moveTo(0, height / 2);
  ctx.lineTo(width, height / 2);
  ctx.stroke();

  const renderPromise = new Promise((resolve) => {
    const img = new Image();
    const blob = new Blob([WORLD_LAND_SVG], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);

    img.onload = () => {
      // 4. Draw Continental Landmass Glow Layer
      ctx.shadowColor = '#00f0ff';
      ctx.shadowBlur = 14;
      ctx.fillStyle = 'rgba(0, 240, 255, 0.12)';
      ctx.drawImage(img, 0, 0, width, height);

      // Inner continent fill
      ctx.shadowBlur = 0;
      ctx.fillStyle = 'rgba(10, 32, 64, 0.85)';
      ctx.drawImage(img, 0, 0, width, height);

      // 5. Global City Lights Radial Glows
      const cities = [
        [37.77, -122.41, '#00f0ff', 18], // San Francisco
        [40.71, -74.00, '#00f0ff', 20],  // New York
        [51.50, -0.12, '#00f0ff', 20],   // London
        [48.85, 2.35, '#ff2e93', 16],    // Paris
        [35.67, 139.65, '#a855f7', 22],  // Tokyo
        [22.31, 114.16, '#00f0ff', 18],  // Hong Kong
        [-33.86, 151.20, '#ff2e93', 18], // Sydney
        [-22.90, -43.17, '#ff2e93', 18], // Rio de Janeiro
        [28.61, 77.20, '#00f0ff', 16],   // New Delhi
        [1.35, 103.81, '#00f0ff', 14],   // Singapore
        [25.20, 55.27, '#ff2e93', 14]    // Dubai
      ];

      cities.forEach(([cLat, cLon, cColor, cRad]) => {
        const cx = ((cLon + 180) / 360) * width;
        const cy = ((90 - cLat) / 180) * height;
        const cGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, cRad);
        cGrad.addColorStop(0, 'rgba(255, 255, 255, 0.95)');
        cGrad.addColorStop(0.4, cColor);
        cGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = cGrad;
        ctx.beginPath();
        ctx.arc(cx, cy, cRad, 0, Math.PI * 2);
        ctx.fill();
      });

      URL.revokeObjectURL(url);
      resolve(canvas);
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      resolve(canvas);
    };

    img.src = url;
  });

  return { canvas, renderPromise };
}

/**
 * Generates a high-precision anti-aliased circular dot texture for PointsMaterial
 */
export function createCircleDotTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');

  const grad = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0.0, 'rgba(255, 255, 255, 1.0)');
  grad.addColorStop(0.65, 'rgba(255, 255, 255, 0.95)');
  grad.addColorStop(0.9, 'rgba(255, 255, 255, 0.25)');
  grad.addColorStop(1.0, 'rgba(255, 255, 255, 0.0)');

  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(32, 32, 30, 0, Math.PI * 2);
  ctx.fill();

  return canvas;
}

/**
 * Generates an Equal-Area / Uniform Dot Matrix Pixel Globe dataset
 * @param {Object} landSampler Landmass detection sampler
 * @param {number} globeRadius Radius of the globe in Three.js units
 * @param {number} latStepDeg Latitude ring increment
 */
export function generatePixelGlobeData(landSampler, globeRadius = 290, latStepDeg = 1.6) {
  const latStepRad = (latStepDeg * Math.PI) / 180;
  const minLat = -82;
  const maxLat = 82;
  const numRings = Math.floor((maxLat - minLat) / latStepDeg);

  const dots = [];

  for (let r = 0; r <= numRings; r++) {
    const lat = minLat + r * latStepDeg;
    const latRad = (lat * Math.PI) / 180;
    const cosLat = Math.cos(latRad);
    const numLon = Math.max(1, Math.round((2 * Math.PI * cosLat) / latStepRad));

    for (let l = 0; l < numLon; l++) {
      const lon = -180 + (l / numLon) * 360;
      const isLand = landSampler ? landSampler.isLand(lat, lon) : false;

      const phi = (lat * Math.PI) / 180;
      const theta = (lon * Math.PI) / 180;

      const rOffset = isLand ? globeRadius + 1.2 : globeRadius;
      const x = rOffset * Math.cos(phi) * Math.sin(theta);
      const y = rOffset * Math.sin(phi);
      const z = rOffset * Math.cos(phi) * Math.cos(theta);

      dots.push({
        x, y, z,
        lat, lon,
        isLand
      });
    }
  }

  const totalPoints = dots.length;
  const positions = new Float32Array(totalPoints * 3);
  const colors = new Float32Array(totalPoints * 3);
  const sizes = new Float32Array(totalPoints);

  // High-Tech Cyber Dot Matrix Palette
  const landCyan = [0.0, 0.94, 1.0];     // #00f0ff
  const landWhite = [0.95, 0.98, 1.0];   // #f0f9ff
  const landPink = [1.0, 0.18, 0.58];    // #ff2e93
  const landPurple = [0.66, 0.33, 0.97]; // #a855f7
  const oceanNavy = [0.05, 0.13, 0.24];  // #0d213d

  for (let i = 0; i < totalPoints; i++) {
    const d = dots[i];
    const i3 = i * 3;

    positions[i3]     = d.x;
    positions[i3 + 1] = d.y;
    positions[i3 + 2] = d.z;

    if (d.isLand) {
      // Land Pixel: Vibrant sharp glowing dots
      const rand = Math.random();
      let c = landCyan;
      if (rand > 0.82) c = landWhite;
      else if (rand > 0.70) c = landPink;
      else if (rand > 0.60) c = landPurple;

      colors[i3]     = c[0];
      colors[i3 + 1] = c[1];
      colors[i3 + 2] = c[2];
      sizes[i] = 3.6;
    } else {
      // Ocean Grid Dot: Dark subtle cyber-navy
      colors[i3]     = oceanNavy[0];
      colors[i3 + 1] = oceanNavy[1];
      colors[i3 + 2] = oceanNavy[2];
      sizes[i] = 1.3;
    }
  }

  return { positions, colors, sizes, totalPoints, dots };
}
